FoamFile { version 2.0; format ascii; class dictionary; location "system"; object controlDict; }
application simpleFoam;
startFrom startTime;
startTime 0;
stopAt endTime;
endTime 500;
deltaT 1;
writeControl timeStep;
writeInterval 100;
purgeWrite 0;
writeFormat ascii;
writePrecision 6;
writeCompression off;
timeFormat general;
timePrecision 6;
runTimeModifiable true;

FoamFile { version 2.0; format ascii; class dictionary; location "system"; object fvSolution; }
solvers
{
    p { solver GAMG; tolerance 1e-7; relTol 0.01; smoother DICGaussSeidel; }
    U { solver smoothSolver; smoother symGaussSeidel; tolerance 1e-8; relTol 0.1; }
    k { solver smoothSolver; smoother symGaussSeidel; tolerance 1e-8; relTol 0.1; }
    omega { solver smoothSolver; smoother symGaussSeidel; tolerance 1e-8; relTol 0.1; }
}
SIMPLE
{
    nNonOrthogonalCorrectors 0;
    consistent true;
}
relaxationFactors
{
    fields
    {
        p 0.3;
    }
    equations
    {
        U 0.7;
        k 0.7;
        omega 0.7;
    }
}

FoamFile { version 2.0; format ascii; class volVectorField; location "0"; object U; }
dimensions [0 1 -1 0 0 0 0];
internalField uniform (14.56 1.017 0);
boundaryField
{
    fixedWalls
    {
        type noSlip;
    }
    lid
    {
        type inletOutlet;
        inletValue uniform (14.56 1.017 0);
        value uniform (14.56 1.017 0);
    }
}

FoamFile { version 2.0; format ascii; class volScalarField; location "0"; object p; }
dimensions [0 2 -2 0 0 0 0];
internalField uniform 0;
boundaryField
{
    fixedWalls
    {
        type zeroGradient;
    }
    lid
    {
        type fixedValue;
        value uniform 0;
    }
}

FoamFile { version 2.0; format ascii; class dictionary; location "constant"; object physicalProperties; }
transportModel  Newtonian;
nu              [0 2 -1 0 0 0 0] 1.45e-05;

FoamFile { version 2.0; format ascii; class dictionary; location "constant"; object momentumTransport; }
simulationType  RAS;
RAS
{
    RASModel        kOmegaSST;
    turbulence      on;
    printCoeffs     on;
}

FoamFile { version 2.0; format ascii; class dictionary; location "system"; object fvSchemes; }
ddtSchemes  { default steadyState; }
gradSchemes { default Gauss linear; }
divSchemes
{
    default         none;
    div(phi,U)      Gauss upwind;
    div(phi,k)      Gauss upwind;
    div(phi,omega)  Gauss upwind;
}
laplacianSchemes { default Gauss linear limited 0.5; }
interpolationSchemes { default linear; }
snGradSchemes { default limited 0.5; }

FoamFile { version 2.0; format ascii; class volVectorField; location "0"; object U; }
dimensions [0 1 -1 0 0 0 0];
internalField uniform (14.56 1.017 0);
boundaryField
{
    fixedWalls
    {
        type noSlip;
    }
    lid
    {
        type inletOutlet;
        inletValue uniform (14.56 1.017 0);
        value uniform (14.56 1.017 0);
    }
}

FoamFile
{
    version     2.0;
    format      ascii;
    class       volVectorField;
    location    "0";
    object      U;
}

dimensions      [0 1 -1 0 0 0 0];

internalField   uniform (14.56 1.017 0);

boundaryField
{
    patch0
    {
        type            noSlip;
    }
}
